//! Arena-allocated nodes for the circular doubly-linked polygon ring.
//!
//! The C++ original threads raw `Node*` pointers through every routine. Here
//! nodes live in a `Vec` and are referred to by index; [`NIL`] plays the role of
//! the null pointer.

/// Index standing in for a null node pointer.
pub const NIL: usize = usize::MAX;

pub struct Node {
    /// Index of the vertex in the original input sequence.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in the polygon ring.
    pub prev: usize,
    pub next: usize,

    /// Z-order curve value.
    pub z: i32,

    /// Previous and next nodes in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Indicates whether this is a steiner point.
    pub steiner: bool,
}

/// Storage for all nodes created while triangulating one polygon.
pub struct Arena {
    nodes: Vec<Node>,
}

impl Arena {
    pub fn new() -> Self {
        Arena { nodes: Vec::new() }
    }

    pub fn reserve(&mut self, capacity: usize) {
        self.nodes.reserve(capacity);
    }

    pub fn clear(&mut self) {
        self.nodes.clear();
    }

    /// Allocates a node that is not yet linked to anything.
    pub fn create(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        });
        self.nodes.len() - 1
    }

    #[inline]
    pub fn get(&self, p: usize) -> &Node {
        &self.nodes[p]
    }

    #[inline]
    pub fn get_mut(&mut self, p: usize) -> &mut Node {
        &mut self.nodes[p]
    }

    #[inline]
    pub fn x(&self, p: usize) -> f64 {
        self.nodes[p].x
    }

    #[inline]
    pub fn y(&self, p: usize) -> f64 {
        self.nodes[p].y
    }

    #[inline]
    pub fn idx(&self, p: usize) -> u32 {
        self.nodes[p].i
    }

    #[inline]
    pub fn prev(&self, p: usize) -> usize {
        self.nodes[p].prev
    }

    #[inline]
    pub fn next(&self, p: usize) -> usize {
        self.nodes[p].next
    }

    #[inline]
    pub fn prev_z(&self, p: usize) -> usize {
        self.nodes[p].prev_z
    }

    #[inline]
    pub fn next_z(&self, p: usize) -> usize {
        self.nodes[p].next_z
    }

    #[inline]
    pub fn z(&self, p: usize) -> i32 {
        self.nodes[p].z
    }

    /// Creates a node and splices it into the ring after `last`.
    ///
    /// When `last` is [`NIL`] the node becomes a self-referencing ring of one.
    pub fn insert_node(&mut self, i: u32, x: f64, y: f64, last: usize) -> usize {
        let p = self.create(i, x, y);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }

        p
    }

    /// Unlinks `p` from both the ring and the z-order list.
    pub fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let prev_z = self.nodes[p].prev_z;
        let next_z = self.nodes[p].next_z;
        if prev_z != NIL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NIL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }

    /// Whether two nodes share the same coordinates.
    #[inline]
    pub fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }
}

impl Default for Arena {
    fn default() -> Self {
        Self::new()
    }
}

