//! Ear-clipping polygon triangulation.
//!
//! A `std`-only reimplementation of the `mapbox::earcut` interface: given a
//! polygon as a list of rings (the first being the outer ring, the rest holes),
//! [`earcut`] returns a flat list of vertex indices, three per triangle.
//!
//! The pipeline is the classic one: build a doubly-linked ring in a known
//! winding order, bridge the holes into the outer ring, then repeatedly clip
//! ears. Larger polygons additionally get a z-order (Morton) index over the
//! vertices so the "is any vertex inside this ear?" test can be restricted to
//! the ear's bounding box instead of scanning the whole ring.

use crate::geom::{area, on_segment, point_in_triangle, sign, z_order};
use crate::nodes::{Arena, NIL};

/// Ring count/size below which the z-order index costs more than it saves.
const HASHING_THRESHOLD: i32 = 80;

/// Triangulates `polygon`, returning vertex indices three per triangle.
///
/// Indices are numbered across the concatenation of all rings, so a vertex in
/// the second ring of a polygon whose first ring has 4 points starts at 4.
pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut e = Earcut::new();
    e.run(polygon);
    e.indices
}

pub struct Earcut {
    pub indices: Vec<u32>,
    vertices: usize,
    nodes: Arena,
    hashing: bool,
    min_x: f64,
    min_y: f64,
    inv_size: f64,
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            indices: Vec::new(),
            vertices: 0,
            nodes: Arena::new(),
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            inv_size: 0.0,
        }
    }

    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        let mut threshold = HASHING_THRESHOLD;
        let mut len = 0usize;

        let mut i = 0usize;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }

        // estimate size of nodes and indices
        self.nodes.clear();
        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NIL || self.nodes.prev(outer_node) == self.nodes.next(outer_node) {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use a z-order curve hash later;
        // calculate the polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes.next(outer_node);
            let mut min_x = self.nodes.x(outer_node);
            let mut max_x = min_x;
            let mut min_y = self.nodes.y(outer_node);
            let mut max_y = min_y;
            loop {
                let x = self.nodes.x(p);
                let y = self.nodes.y(p);
                min_x = min_x.min(x);
                min_y = min_y.min(y);
                max_x = max_x.max(x);
                max_y = max_y.max(y);
                p = self.nodes.next(p);
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size are later used to transform coords into
            // integers for the z-order calculation
            self.min_x = min_x;
            self.min_y = min_y;
            let size = (max_x - min_x).max(max_y - min_y);
            self.inv_size = if size != 0.0 { 32767.0 / size } else { 0.0 };
        }

        self.earcut_linked(outer_node, 0);

        self.nodes.clear();
    }

    /// Creates a circular doubly-linked list from the ring, in the requested
    /// winding order.
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let len = points.len();
        let mut sum = 0.0;
        let mut last = NIL;

        // calculate the original winding order of the polygon ring
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = &points[i];
            let p2 = &points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        // link points into a circular doubly-linked list in the specified order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                let idx = (self.vertices + i) as u32;
                last = self.nodes.insert_node(idx, points[i][0], points[i][1], last);
            }
        } else {
            for i in (0..len).rev() {
                let idx = (self.vertices + i) as u32;
                last = self.nodes.insert_node(idx, points[i][0], points[i][1], last);
            }
        }

        if last != NIL && self.nodes.equals(last, self.nodes.next(last)) {
            self.nodes.remove_node(last);
            last = self.nodes.next(last);
        }

        self.vertices += len;

        last
    }

    /// Eliminates colinear or duplicate points.
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut end = if end == NIL { start } else { end };

        let mut p = start;
        let mut again;
        loop {
            again = false;

            let next = self.nodes.next(p);
            let prev = self.nodes.prev(p);
            if !self.nodes.get(p).steiner
                && (self.nodes.equals(p, next) || self.area(prev, p, next) == 0.0)
            {
                self.nodes.remove_node(p);
                p = self.nodes.prev(p);
                end = p;

                if p == self.nodes.next(p) {
                    break;
                }
                again = true;
            } else {
                p = next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear-slicing loop which triangulates a polygon (given as a linked
    /// list).
    fn earcut_linked(&mut self, ear_start: usize, pass: i32) {
        let mut ear = ear_start;
        if ear == NIL {
            return;
        }

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes.prev(ear) != self.nodes.next(ear) {
            let prev = self.nodes.prev(ear);
            let next = self.nodes.next(ear);

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes.idx(prev));
                self.indices.push(self.nodes.idx(ear));
                self.indices.push(self.nodes.idx(next));

                self.nodes.remove_node(ear);

                // skipping the next vertex leads to fewer sliver triangles
                ear = self.nodes.next(next);
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find
            // any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let filtered = self.filter_points(ear, NIL);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small
                    // self-intersections locally
                    let filtered = self.filter_points(ear, NIL);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon
                    // into two
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Whether the ear at `ear` is valid, checking every other vertex.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes.prev(ear);
        let b = ear;
        let c = self.nodes.next(ear);

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let (ax, ay) = (self.nodes.x(a), self.nodes.y(a));
        let (bx, by) = (self.nodes.x(b), self.nodes.y(b));
        let (cx, cy) = (self.nodes.x(c), self.nodes.y(c));

        let mut p = self.nodes.next(self.nodes.next(ear));

        while p != self.nodes.prev(ear) {
            if point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes.x(p), self.nodes.y(p))
                && self.area(self.nodes.prev(p), p, self.nodes.next(p)) >= 0.0
            {
                return false;
            }
            p = self.nodes.next(p);
        }

        true
    }

    /// Whether the ear at `ear` is valid, using the z-order index to only visit
    /// vertices within the ear's bounding box.
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes.prev(ear);
        let b = ear;
        let c = self.nodes.next(ear);

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes.x(a), self.nodes.y(a));
        let (bx, by) = (self.nodes.x(b), self.nodes.y(b));
        let (cx, cy) = (self.nodes.x(c), self.nodes.y(c));

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx.min(cx));
        let min_ty = ay.min(by.min(cy));
        let max_tx = ax.max(bx.max(cx));
        let max_ty = ay.max(by.max(cy));

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        let ear_prev = self.nodes.prev(ear);
        let ear_next = self.nodes.next(ear);

        let contains = |p: usize| -> bool {
            p != ear_prev
                && p != ear_next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes.x(p), self.nodes.y(p))
                && self.area(self.nodes.prev(p), p, self.nodes.next(p)) >= 0.0
        };

        // look for points inside the triangle in both directions
        let mut p = self.nodes.prev_z(ear);
        let mut n = self.nodes.next_z(ear);

        while p != NIL && self.nodes.z(p) >= min_z && n != NIL && self.nodes.z(n) <= max_z {
            if contains(p) {
                return false;
            }
            p = self.nodes.prev_z(p);

            if contains(n) {
                return false;
            }
            n = self.nodes.next_z(n);
        }

        // look for remaining points in decreasing z-order
        while p != NIL && self.nodes.z(p) >= min_z {
            if contains(p) {
                return false;
            }
            p = self.nodes.prev_z(p);
        }

        // look for remaining points in increasing z-order
        while n != NIL && self.nodes.z(n) <= max_z {
            if contains(n) {
                return false;
            }
            n = self.nodes.next_z(n);
        }

        true
    }

    /// Goes through all polygon nodes and cures small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut start = start;
        let mut p = start;
        loop {
            let a = self.nodes.prev(p);
            let pn = self.nodes.next(p);
            let b = self.nodes.next(pn);

            if !self.nodes.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes.idx(a));
                self.indices.push(self.nodes.idx(p));
                self.indices.push(self.nodes.idx(b));

                // remove the two nodes involved
                self.nodes.remove_node(p);
                let pn = self.nodes.next(p);
                self.nodes.remove_node(pn);

                p = b;
                start = b;
            }

            p = self.nodes.next(p);
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// Tries splitting the polygon into two along a valid diagonal, then
    /// triangulates each half.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes.next(self.nodes.next(a));
            while b != self.nodes.prev(a) {
                if self.nodes.idx(a) != self.nodes.idx(b) && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes.next(a);
                    a = self.filter_points(a, a_next);
                    let c_next = self.nodes.next(c);
                    c = self.filter_points(c, c_next);

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes.next(b);
            }
            a = self.nodes.next(a);
            if a == start {
                break;
            }
        }
    }

    /// Links every hole into the outer loop, producing a single-ring polygon
    /// without holes.
    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node: usize) -> usize {
        let mut outer_node = outer_node;
        let mut queue: Vec<usize> = Vec::new();

        for ring in &points[1..] {
            let list = self.linked_list(ring, false);
            if list != NIL {
                if list == self.nodes.next(list) {
                    self.nodes.get_mut(list).steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        queue.sort_by(|&a, &b| {
            self.nodes
                .x(a)
                .partial_cmp(&self.nodes.x(b))
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        // process holes from left to right
        for hole in queue {
            self.eliminate_hole(hole, outer_node);
            let next = self.nodes.next(outer_node);
            outer_node = self.filter_points(outer_node, next);
        }

        outer_node
    }

    /// Finds a bridge between the hole and the outer ring and splices them.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge != NIL {
            let b = self.split_polygon(bridge, hole);

            // filter collinear points around the cuts
            let bridge_next = self.nodes.next(bridge);
            self.filter_points(bridge, bridge_next);
            let b_next = self.nodes.next(b);
            self.filter_points(b, b_next);
        }
    }

    /// Finds the outer-ring vertex a hole's leftmost vertex can be bridged to.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let hx = self.nodes.x(hole);
        let hy = self.nodes.y(hole);
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost vertex
        // to the left; the segment's endpoint with lesser x will be the
        // potential connection vertex
        let mut p = outer_node;
        loop {
            let pn = self.nodes.next(p);
            let (py, pny) = (self.nodes.y(p), self.nodes.y(pn));
            if hy <= py && hy >= pny && pny != py {
                let px = self.nodes.x(p);
                let x = px + (hy - py) * (self.nodes.x(pn) - px) / (pny - py);
                if x <= hx && x > qx {
                    qx = x;
                    m = if px < self.nodes.x(pn) { p } else { pn };
                    if x == hx {
                        // hole touches outer segment; pick the leftmost endpoint
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // look for points inside the triangle of the hole vertex, the segment
        // intersection and the endpoint; if there are no points found we have a
        // valid connection, otherwise choose the vertex of the minimum angle
        // with the ray as the connection vertex
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.nodes.x(m);
        let my = self.nodes.y(m);

        let mut p = m;
        loop {
            let px = self.nodes.x(p);
            let py = self.nodes.y(p);
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px);

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.nodes.x(m) || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.nodes.next(p);
            if p == stop {
                break;
            }
        }

        m
    }

    /// Whether sector m contains sector p in the same coordinates.
    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.nodes.prev(m), m, self.nodes.prev(p)) < 0.0
            && self.area(self.nodes.next(p), m, self.nodes.next(m)) < 0.0
    }

    /// Interlinks polygon nodes in z-order.
    fn index_curve(&mut self, start: usize) {
        let mut p = start;

        loop {
            if self.nodes.z(p) == 0 {
                let z = self.z_order(self.nodes.x(p), self.nodes.y(p));
                self.nodes.get_mut(p).z = z;
            }
            let prev = self.nodes.prev(p);
            let next = self.nodes.next(p);
            self.nodes.get_mut(p).prev_z = prev;
            self.nodes.get_mut(p).next_z = next;
            p = next;
            if p == start {
                break;
            }
        }

        let prev_z = self.nodes.prev_z(p);
        self.nodes.get_mut(prev_z).next_z = NIL;
        self.nodes.get_mut(p).prev_z = NIL;

        self.sort_linked(p);
    }

    /// Simon Tatham's linked-list merge sort, ordering the z-list by `z`.
    fn sort_linked(&mut self, list: usize) -> usize {
        let mut list = list;
        let mut in_size = 1i32;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0i32;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes.next_z(q);
                    if q == NIL {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes.next_z(q);
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.nodes.next_z(p);
                        p_size -= 1;
                    } else if self.nodes.z(p) <= self.nodes.z(q) {
                        e = p;
                        p = self.nodes.next_z(p);
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes.next_z(q);
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.nodes.get_mut(tail).next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes.get_mut(e).prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            if tail != NIL {
                self.nodes.get_mut(tail).next_z = NIL;
            }

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    /// Finds the leftmost node of a polygon ring.
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes.x(p) < self.nodes.x(leftmost)
                || (self.nodes.x(p) == self.nodes.x(leftmost)
                    && self.nodes.y(p) < self.nodes.y(leftmost))
            {
                leftmost = p;
            }
            p = self.nodes.next(p);
            if p == start {
                break;
            }
        }

        leftmost
    }

    /// Whether the diagonal between two polygon nodes is valid: it lies inside
    /// the polygon and does not intersect any edge.
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let (an, ap) = (self.nodes.next(a), self.nodes.prev(a));
        let bi = self.nodes.idx(b);

        self.nodes.idx(an) != bi
            && self.nodes.idx(ap) != bi
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                // does not create opposite-facing sectors
                && (self.area(ap, a, self.nodes.prev(b)) != 0.0
                    || self.area(a, self.nodes.prev(b), b) != 0.0))
                // special zero-length case
                || (self.nodes.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(self.nodes.prev(b), b, self.nodes.next(b)) > 0.0))
    }

    #[inline]
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        area(
            self.nodes.x(p),
            self.nodes.y(p),
            self.nodes.x(q),
            self.nodes.y(q),
            self.nodes.x(r),
            self.nodes.y(r),
        )
    }

    #[inline]
    fn z_order(&self, x: f64, y: f64) -> i32 {
        z_order(x, y, self.min_x, self.min_y, self.inv_size)
    }

    /// Whether segments p1q1 and p2q2 intersect.
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        let seg = |p: usize, q: usize, r: usize| {
            on_segment(
                self.nodes.x(p),
                self.nodes.y(p),
                self.nodes.x(q),
                self.nodes.y(q),
                self.nodes.x(r),
                self.nodes.y(r),
            )
        };

        // p1, q1 and p2 are collinear and p2 lies on p1q1
        if o1 == 0 && seg(p1, p2, q1) {
            return true;
        }
        // p1, q1 and q2 are collinear and q2 lies on p1q1
        if o2 == 0 && seg(p1, q2, q1) {
            return true;
        }
        // p2, q2 and p1 are collinear and p1 lies on p2q2
        if o3 == 0 && seg(p2, p1, q2) {
            return true;
        }
        // p2, q2 and q1 are collinear and q1 lies on p2q2
        if o4 == 0 && seg(p2, q1, q2) {
            return true;
        }

        false
    }

    /// Whether the polygon edges intersect the segment ab.
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let (ai, bi) = (self.nodes.idx(a), self.nodes.idx(b));
        let mut p = a;
        loop {
            let pn = self.nodes.next(p);
            let (pi, pni) = (self.nodes.idx(p), self.nodes.idx(pn));
            if pi != ai && pni != ai && pi != bi && pni != bi && self.intersects(p, pn, a, b) {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        false
    }

    /// Whether the segment ab goes inside the polygon at vertex a.
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.nodes.prev(a);
        let an = self.nodes.next(a);
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    /// Whether the middle of the segment ab lies inside the polygon.
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut inside = false;
        let px = (self.nodes.x(a) + self.nodes.x(b)) / 2.0;
        let py = (self.nodes.y(a) + self.nodes.y(b)) / 2.0;

        let mut p = a;
        loop {
            let pn = self.nodes.next(p);
            let (y, ny) = (self.nodes.y(p), self.nodes.y(pn));
            if ((y > py) != (ny > py))
                && ny != y
                && (px < (self.nodes.x(pn) - self.nodes.x(p)) * (py - y) / (ny - y) + self.nodes.x(p))
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        inside
    }

    /// Links two polygon vertices with a bridge; if the vertices belong to the
    /// same ring this splits it in two, otherwise it merges the two rings.
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self
            .nodes
            .create(self.nodes.idx(a), self.nodes.x(a), self.nodes.y(a));
        let b2 = self
            .nodes
            .create(self.nodes.idx(b), self.nodes.x(b), self.nodes.y(b));
        let an = self.nodes.next(a);
        let bp = self.nodes.prev(b);

        self.nodes.get_mut(a).next = b;
        self.nodes.get_mut(b).prev = a;

        self.nodes.get_mut(a2).next = an;
        self.nodes.get_mut(an).prev = a2;

        self.nodes.get_mut(b2).next = a2;
        self.nodes.get_mut(a2).prev = b2;

        self.nodes.get_mut(bp).next = b2;
        self.nodes.get_mut(b2).prev = bp;

        b2
    }
}

impl Default for Earcut {
    fn default() -> Self {
        Self::new()
    }
}

