//! Command-line argument helpers.

/// Parses a leading decimal integer the way C's `atoi` does.
///
/// Leading whitespace and an optional sign are accepted, parsing stops at the
/// first character that is not a digit, and unparsable input yields `0`.
/// Out-of-range input saturates in `i64` and is then truncated to `i32`, which
/// is what `atoi` (implemented on top of `strtol`) does on 64-bit platforms.
pub fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = (bytes[i] - b'0') as i64;
        value = value
            .saturating_mul(10)
            .saturating_add(if negative { -digit } else { digit });
        i += 1;
    }

    value as i32
}

#[cfg(test)]
mod tests {
    use super::atoi;

    #[test]
    fn parses_like_c_atoi() {
        assert_eq!(atoi("1"), 1);
        assert_eq!(atoi("  42abc"), 42);
        assert_eq!(atoi("-7"), -7);
        assert_eq!(atoi("+3"), 3);
        assert_eq!(atoi("abc"), 0);
        assert_eq!(atoi(""), 0);
    }
}

