use std::io::Write;

#[path = "src/cli.rs"]
mod cli;
#[path = "src/earcut.rs"]
mod earcut;
#[path = "src/geom.rs"]
mod geom;
#[path = "src/nodes.rs"]
mod nodes;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut n: i32 = 1;
    if args.len() > 1 {
        n = cli::atoi(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
    let mut ring: Vec<[f64; 2]> = Vec::new();

    let count = n.wrapping_mul(3);
    let mut i: i32 = 0;
    while i < count {
        let angle = 2.0 * std::f64::consts::PI * f64::from(i) / f64::from(count);
        ring.push([angle.cos(), angle.sin()]);
        i += 1;
    }
    polygon.push(ring);

    let indices = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for idx in indices {
        write!(out, "{} ", idx).unwrap();
    }
    out.flush().unwrap();
}

